# Final integrity check of /work/edited
import torch, os
expected = {10:[2], 12:[32], 14:[1328], 16:[173], 17:[20,121,139], 18:[1261], 19:[31], 20:[1111], 5:[189]}
ok = True
for f in sorted(os.listdir('/work/edited')):
    name = f[:-len('.safetensors')]
    cur = load(name); orig = load_original(name)
    if cur.shape != orig.shape or cur.dtype != orig.dtype:
        print('SHAPE/DTYPE MISMATCH', name); ok = False; continue
    L = int(name.split('layers.')[1].split('.')[0])
    d = (cur != orig)
    cols = d.any(dim=0).nonzero().flatten().tolist()
    if cols != expected[L]:
        print('COL MISMATCH', name, cols); ok = False; continue
    if not (cur[:, cols] == 0).all():
        print('NOT ZERO', name); ok = False; continue
    if d.any(dim=1).any(dim=0).sum() != len(cols):
        print('EXTRA DIFFS', name); ok = False; continue
print('integrity OK' if ok else 'PROBLEM', '| files:', len(os.listdir('/work/edited')))
